#include "../charge_compiler/json.hpp"
#include "sparse_runs_v2.hpp"
#include <array>
#include <iostream>
#include <time.h>
using I=long long;
static double now(){timespec t{};require(clock_gettime(CLOCK_BOOTTIME,&t)==0,"clock");return t.tv_sec+t.tv_nsec*1e-9;}
struct Map{uint64_t targets;std::vector<uint32_t> values;};
static Map mapping(const std::string&path,const std::string&magic="CNETDOF1"){std::ifstream in(path,std::ios::binary);require(bool(in),"map open");char h[24];in.read(h,24);require(bool(in)&&std::string(h,8)==magic,"map magic");uint64_t n=sparse::load(h+8),t=sparse::load(h+16);require(n&&n<=UINT32_MAX&&t&&t<=UINT32_MAX,"map dimensions");Map m{t,std::vector<uint32_t>(n)};in.read((char*)m.values.data(),n*4);require(bool(in),"map entries");char extra;require(!in.get(extra)&&in.eof(),"map end");for(auto v:m.values)require(v<t,"map targets");return m;}
int main(int argc,char**argv){try{
 require(argc==2,"usage CONFIG");auto cfg=Json::read(argv[1]);double deadline=cfg.at("deadline_uptime").num();auto zero=mapping(cfg.at("zero_map").str()),components=mapping(cfg.at("components").str()),fields=mapping(cfg.at("field_nets").str(),"CNETFLD1");require(zero.targets==components.values.size()&&fields.targets==components.targets,"common voltage/conductor namespaces");
 require(zero.values[0]==0&&components.values[0]==0&&fields.values[0]==0,"abstract reference map identity");
 std::vector<uint8_t> roles(components.targets,3),seen_fields(fields.values.size(),0);roles[0]=0;
 auto component=[&](I original){require(original>=0&&uint64_t(original)<zero.values.size(),"native voltage bounds");return components.values[zero.values[original]];};
 std::ifstream input(cfg.at("devices").str());require(bool(input),"device join open");std::string line;uint64_t devices=0,terminals=0,ports=0;
 while(std::getline(input,line)){auto r=Json::parse(line);for(auto&t:r.at("terminals").arr()){uint32_t c=component(t.at(2).integer());require(c!=0,"native device must not bind abstract reference");roles[c]=1;terminals++;}devices++;}require(input.eof(),"complete device join");
 auto port_list=Json::read(cfg.at("ports").str());for(auto&p:port_list.arr()){I original=p.at("original_voltage_id").integer();uint32_t c=component(original);require(I(zero.values[original])==p.at("constrained_voltage_id").integer()&&c!=0,"external port transform/reference");roles[c]=1;ports++;}
 std::ifstream index(cfg.at("floating_index").str(),std::ios::binary);require(bool(index),"floating index open");char header[16];index.read(header,16);require(bool(index)&&std::string(header,8)=="FBSIDX01"&&sparse::load(header+8)==fields.values.size(),"floating index header");
 input.close();input.open(cfg.at("floating_nodes").str());require(bool(input),"floating node map open");uint64_t floating=0,floating_voltages=0;
 while(std::getline(input,line)){if(floating%10000==0)require(now()<deadline,"component role deadline");auto row=Json::parse(line);I field=row.at(0).integer(),base=row.at(1).integer(),n=row.at(2).integer();require(field>0&&uint64_t(field)<fields.values.size()&&!seen_fields[field],"unique physical floating field");seen_fields[field]=1;require(base>0&&n>0&&uint64_t(base+n)<=zero.values.size(),"floating original voltage interval");index.seekg(16+16*field);char entry[16];index.read(entry,16);require(bool(index),"floating index record");uint32_t length=uint8_t(entry[8])|uint32_t(uint8_t(entry[9]))<<8|uint32_t(uint8_t(entry[10]))<<16|uint32_t(uint8_t(entry[11]))<<24;require(length>0,"floating field registered in basis index");uint32_t c=fields.values[field];require(c!=0&&roles[c]==3,"floating conductor unique and unattached");
 for(I k=0;k<n;k++){require(component(base+k)==c,"every floating basis voltage in its original conductor");require(zero.values[base+k]==zero.values[base]+k,"floating basis has no native zero-R voltage aliases");}roles[c]=2;floating++;floating_voltages+=n;}
 require(input.eof(),"complete floating map");require(floating==uint64_t(cfg.at("expected_floating").integer()),"complete physical floating basis inventory");
 std::array<uint64_t,4> counts{};for(auto r:roles)counts[r]++;std::ofstream output(cfg.at("role_output").str(),std::ios::binary);output.write("GROLE001",8);char h[16];sparse::store(h,roles.size());sparse::store(h+8,4);output.write(h,16);output.write((char*)roles.data(),roles.size());output.close();require(bool(output),"role output close");
 std::ofstream unattached(cfg.at("unattached_output").str(),std::ios::binary);unattached.write("GUNATT01",8);sparse::store(h,counts[2]+counts[3]);sparse::store(h+8,roles.size());unattached.write(h,16);for(uint32_t c=0;c<roles.size();c++)if(roles[c]>=2)unattached.write((char*)&c,4);unattached.close();require(bool(unattached),"unattached output close");
 Json report=Json::object();report["native_devices"]=I(devices);report["native_terminal_bindings"]=I(terminals);report["external_ports"]=I(ports);report["unextracted_floating_components"]=I(floating);report["unextracted_floating_voltage_states"]=I(floating_voltages);report["abstract_reference_components"]=I(counts[0]);report["device_or_port_attached_components"]=I(counts[1]);report["other_native_R_components_without_device_or_port"]=I(counts[3]);report["all_components_without_device_or_port"]=I(counts[2]+counts[3]);std::ofstream summary(cfg.at("report").str());summary<<report.dump()<<'\n';require(bool(summary),"role report close");return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
